questionvariables.text:
stack_include_contrib("prooflib.mac");

/****************************************************************/
/* Theorem statement */
thm: "If two parallel lines are cut by a transversal, then alternate exterior angles are equal.";

/****************************************************************/
/* Proof steps */
proof_steps: [
    ["assumption", "Let lines \\(AB\\) and \\(CD\\) be parallel, cut by transversal \\(XY\\)."],
    ["step1", "Note that \\(\\angle BO_1Y\\) and \\(\\angle AO_1O_2\\) are vertically opposite angles, so they are equal."],
    ["step2", "Since \\(AB \\parallel CD\\), by the corresponding angles theorem, \\(\\angle AO_1O_2 = \\angle CO_2X\\)."],
    ["conclusion", "Therefore, \\(\\angle BO_1Y = \\angle CO_2X\\)."]
];

/****************************************************************/
/* Correct proof order */
proof_ans: proof("assumption","step1","step2","conclusion");

/* Randomize steps for Parsons-style task */
proof_steps: random_permutation(proof_steps);

/* Generate alternatives for STACK marking */
tal: proof_alternatives(proof_ans);
len1: length(tal);

/* Flatten proofs for feedback display */
tas: setify(map(proof_flatten, tal));
